data=json.dumps(j,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
page=r'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Atlas Home · Open Suite</title><style>
:root{--bg:#101924;--panel:#1b2936;--panel2:#213342;--ink:#edf1ea;--muted:#b7c5ca;--accent:#f0c87d;--green:#8ed7b3;--line:#415669;--focus:#f1d388}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 5% 0%,#294448 0%,#101924 57%);font:16px/1.54 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink)}button,input,select{font:inherit}button,a,input,select{outline-offset:3px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--focus)}.shell{max-width:1250px;margin:auto;padding:28px clamp(16px,4vw,55px) 60px}.eyebrow{font-weight:700;letter-spacing:.18em;font-size:.72rem;text-transform:uppercase;color:var(--green)}header{display:flex;justify-content:space-between;align-items:center;gap:15px;border-bottom:1px solid var(--line);padding-bottom:18px}.logo{font-size:1.5rem;letter-spacing:-.04em;font-weight:800;color:var(--ink)}.logo span{color:var(--accent)}.quiet{font-size:.83rem;color:var(--muted)}.hero{padding:45px 0 28px;display:grid;grid-template-columns:1.4fr .8fr;gap:25px;align-items:center}h1{font-weight:650;font-size:clamp(2.2rem,6vw,4.2rem);line-height:1.05;letter-spacing:-.05em;margin:10px 0 16px}h1 em{font-style:normal;color:var(--accent)}p{color:var(--muted);max-width:70ch}.note{border:1px solid #57726d;background:#20383a;border-radius:20px;padding:25px}.note .large{font-weight:700;color:var(--green);font-size:1.12rem}.note small{color:var(--muted)}.metrics{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}.metric{border:1px solid var(--line);border-radius:14px;padding:9px 13px;background:#20303b}.metric b{display:block}.metric span{font-size:.76rem;color:var(--muted)}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:17px 0 25px}.search{flex:1;min-width:210px;padding:11px 15px;border-radius:12px;background:#1f303c;color:var(--ink);border:1px solid var(--line)}select{background:#1f303c;color:var(--ink);padding:11px 12px;border:1px solid var(--line);border-radius:12px}.btn{border:1px solid var(--line);border-radius:12px;padding:10px 13px;color:var(--ink);background:#2b4350;cursor:pointer}.btn:hover{background:#395563}.btn.primary{background:var(--accent);color:#192b32;border-color:var(--accent);font-weight:800}.btn.dim{opacity:.75}.row{display:flex;justify-content:space-between;align-items:center;gap:12px}h2{font-size:1.25rem;letter-spacing:-.02em;margin:20px 0 10px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.card{border:1px solid var(--line);background:var(--panel);border-radius:18px;padding:18px;display:flex;flex-direction:column;gap:9px;min-height:216px}.card:hover{border-color:#9cacae}.card .label{font-size:.75rem;color:var(--green);text-transform:uppercase;letter-spacing:.07em}.card h3{font-size:1.2rem;margin:0}.card p{font-size:.87rem;line-height:1.47;margin:0;flex:1}.badge{font-size:.72rem;display:inline-block;border:1px solid #677f88;color:#dae1dc;padding:2px 7px;border-radius:8px;width:max-content}.badge.alpha{border-color:#bf8b65;color:#eac594}.card .actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:4px}.a{font-size:.84rem;color:var(--accent)}.a:hover{color:#fff}.box{margin-top:28px;background:var(--panel2);border:1px solid var(--line);padding:22px;border-radius:18px}.box h2{margin-top:0}.layout{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}.status{padding:14px;border-radius:12px;background:#152937;font-size:.87rem;color:#cce0d8;min-height:54px;white-space:pre-wrap}.notice{font-size:.8rem;color:var(--muted)}ol{padding-left:22px}li{padding:4px 0}.empty{grid-column:1/-1;padding:20px;border:1px dashed var(--line);border-radius:14px}footer{margin-top:40px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:.83rem}@media(max-width:900px){.hero,.layout{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:610px){.grid{grid-template-columns:1fr}.shell{padding:15px}.hero{padding-top:30px}h1{font-size:2.5rem}header{align-items:flex-start}.note{padding:18px}}@media(prefers-reduced-motion:no-preference){button{transition:background .14s} .card{transition:border .14s}}
</style></head><body><div class="shell"><header><div class="logo">ATLAS<span> / </span>OPEN SUITE</div><div class="quiet">Offline inspection · no accounts · no telemetry</div></header>
<section class="hero"><div><div class="eyebrow">One computer. Your tools. Your choice.</div><h1>Make great things.<br><em>Keep what you make.</em></h1><p>Curated open-source tools for documents, spreadsheets, photos, movies, music, games and everything in between. Keep familiar interfaces, keep source credit, and choose the apps that actually earn their place.</p><div class="metrics"><div class="metric"><b id="count">—</b><span>source candidates</span></div><div class="metric"><b>0</b><span>apps installed</span></div><div class="metric"><b>0</b><span>accounts created</span></div></div></div><aside class="note"><div class="eyebrow">Atlas identity</div><p class="large">Unlock once. Choose what each app may access.</p><p>Local tools should work without accounts. Compatible services may use scoped OpenID Connect or per-site passkeys. Nothing can force a third-party service to accept your desktop login.</p><small>TPM/passkey integration and hosted SSO are design targets, not running capabilities.</small></aside></section>
<section class="row" style="flex-wrap:wrap;gap:10px;margin-bottom:12px" aria-label="Curated starter bundles"><span class="quiet">Start with a familiar setup</span><div style="display:flex;flex-wrap:wrap;gap:8px"><button class="btn" type="button" data-bundle="everyday">Everyday</button><button class="btn" type="button" data-bundle="creator">Creator studio</button><button class="btn" type="button" data-bundle="game">Games</button><button class="btn" type="button" data-bundle="privacy">Privacy</button></div></section><div class="toolbar"><label for="search">Find the right tool</label><input class="search" id="search" type="search" autocomplete="off" placeholder="Try spreadsheet, video, photo, browser…"/><label for="category">Category</label><select id="category"><option value="">All categories</option></select><label for="tier">Curation</label><select id="tier"><option value="">All candidates</option><option value="CORE_CANDIDATE">Everyday core</option><option value="OPTIONAL_CANDIDATE">Optional</option><option value="PREVIEW_ONLY">ArtCraft preview</option><option value="INFRASTRUCTURE">Infrastructure</option></select><button class="btn" id="reset" type="button">Clear filters</button></div>
<div class="row"><h2>Tools, not subscriptions</h2><span class="quiet" id="visible">—</span></div><div id="grid" class="grid" aria-live="polite"></div>
<section class="layout"><div class="box" id="plan"><div class="row"><h2>Your installation plan</h2><button type="button" id="clearPlan" class="btn">Clear plan</button></div><p>Make a list. Atlas will demand exact publisher, artifact, license, compatibility, user consent and rollback proof before any future installer can act.</p><ol id="chosen"><li>No software selected</li></ol><div class="status" id="planStatus" role="status">Planning only. Nothing is installed.</div></div><div class="box"><h2>Security without a dozen dashboards</h2><p>Hardened browsing, optional VPN, verified updates and one-click emergency containment—when those native services are independently verified.</p><div class="actions"><button type="button" class="btn" id="showVpn">VPN readiness</button> <button type="button" class="btn" id="showAuth">Sign-in model</button></div><p class="status" id="securityStatus" role="status">Default: no VPN is active; no credential is stored; no security action is performed.</p></div></section>
<section class="box"><h2>Source provenance and license review</h2><p id="provenance">Select an app's “Why this tool?” link to inspect its source, license claim, maturity and compatibility caution. Atlas will not copy another team's logo or UI assets just because its code is open.</p></section><footer>Atlas OS Open Suite R01 · Local source-only candidate · Ariadne identities remain independent from app IDs · CANON R13 is review material, not deployment authority. Paid hosting, storage, licensed media, VPN endpoints and optional AI services may still incur costs.</footer></div>
<script type="application/json" id="atlas-data">__CATALOG__</script><script>
'use strict';const source=JSON.parse(document.getElementById('atlas-data').textContent);const items=source.items;const selection=new Set();const $=id=>document.getElementById(id);const grid=$('grid'),chosen=$('chosen');const categories=[...new Set(items.map(x=>x.category))].sort();for(const c of categories){const o=document.createElement('option');o.value=c;o.textContent=c;$('category').append(o)}
$('count').textContent=String(items.length);function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function render(){grid.replaceChildren();const q=$('search').value.trim().toLowerCase();const cat=$('category').value, tier=$('tier').value;const records=items.filter(x=>(!q||`${x.name} ${x.category} ${x.notes} ${x.formats.join(' ')}`.toLowerCase().includes(q))&&(!cat||x.category===cat)&&(!tier||x.slot===tier));$('visible').textContent=`${records.length} shown`;if(!records.length)grid.append(el('div','empty','No matching tools yet. Clear the filters or search by what you want to create.'));
for(const x of records){const card=el('article','card');card.append(el('div','label',x.category));card.append(el('h3',null,x.name));card.append(el('span','badge'+(x.slot==='PREVIEW_ONLY'?' alpha':''),x.slot==='CORE_CANDIDATE'?'Everyday candidate':x.slot==='PREVIEW_ONLY'?'Experimental preview':x.slot==='OPTIONAL_CANDIDATE'?'Optional candidate':'Infrastructure, not preloaded'));card.append(el('p',null,x.notes||'Source-first open software candidate. Exact release and license review pending.'));const actions=el('div','actions');const add=el('button','btn',selection.has(x.id)?'Remove from plan':'Add to plan');add.type='button';add.dataset.app=x.id;add.addEventListener('click',()=>{selection.has(x.id)?selection.delete(x.id):selection.add(x.id);updatePlan();render()});actions.append(add);const why=el('button','btn dim','Why this tool?');why.type='button';why.addEventListener('click',()=>{let p=$('provenance');p.replaceChildren(el('strong',null,x.name),el('p',null,`${x.maturity.replaceAll('_',' ')} · ${x.auth} · ${x.license_claim} (unverified exact release/license/assets). ${x.notes}`));const links=el('p');for(const [label,url] of [['Official project',x.origin],['Source code',x.repo]]){const a=el('a','a',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a,document.createTextNode('  ·  '))}p.append(links);p.scrollIntoView({behavior:'smooth',block:'nearest'})});actions.append(why);card.append(actions);grid.append(card)}}
function updatePlan(){chosen.replaceChildren();for(const id of selection){const x=items.find(a=>a.id===id);chosen.append(el('li',null,`${x.name} — ${x.slot==='PREVIEW_ONLY'?'preview/alpha':'candidate'}; license, publisher and artifact verification pending`))}if(!selection.size)chosen.append(el('li',null,'No software selected'));$('planStatus').textContent=selection.size?`${selection.size} item${selection.size>1?'s':''} proposed. Not installed. Before installation: review exact upstream source and license/assets; verify signed package, sandbox permissions, OS compatibility, and backup/rollback. ${[...selection].some(id=>items.find(x=>x.id===id).requires_server)?'Server-based apps also need an opt-in provider, storage, identity and backups.':''}`:'Planning only. Nothing is installed.'}
const bundles={everyday:['libreoffice','librewolf','vlc','keepassxc'],creator:['libreoffice','gimp','krita','inkscape','kdenlive','obs','audacity'],game:['luanti','godot','supertuxkart','openttd'],privacy:['librewolf','keepassxc','wireguard','syncthing']};document.querySelectorAll('[data-bundle]').forEach(b=>b.addEventListener('click',()=>{selection.clear();for(const id of bundles[b.dataset.bundle]){if(items.some(a=>a.id===id))selection.add(id)}updatePlan();render();$('plan').scrollIntoView({behavior:'smooth',block:'center'})}));$('search').addEventListener('input',render);$('category').addEventListener('change',render);$('tier').addEventListener('change',render);$('reset').addEventListener('click',()=>{$('search').value='';$('category').value='';$('tier').value='';render()});$('clearPlan').addEventListener('click',()=>{selection.clear();updatePlan();render()});$('showVpn').addEventListener('click',()=>{$('securityStatus').textContent='WireGuard is a VPN protocol/client, not a free VPN provider. An approved endpoint, user opt-in, kill-switch and DNS-leak checks are required. Atlas has not configured or activated a tunnel.'});$('showAuth').addEventListener('click',()=>{$('securityStatus').textContent='Future Atlas login: device-local presence + protected key, then per-app scoped sessions. OIDC-capable apps can share an identity provider after explicit enrollment; independent third-party websites still require their own valid passkey or sign-in. No biometrics, tokens, passwords or cookies were read or stored here.'});render();updatePlan();
</script></body></html>'''
(ROOT/'web/atlas-open-suite.html').write_text(page.replace('__CATALOG__',data),encoding='utf-8')
print('HTML', (ROOT/'web/atlas-open-suite.html').stat().st_size)
